"""Reproducible original Neo-Eldarin learning data. Does not copy source course texts/exercises."""
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]
def example(text, hl, zh, en):
    assert hl in text
    return dict(text=text, hl=hl, zh=zh, en=en)
def grammar(level, ident, zh, form, meaning_zh, meaning_en, a, b):
    return dict(id=ident, level=level, name=dict(zh=zh,en=form), form=dict(zh=form,en=form),
                meaning=dict(zh=meaning_zh,en=meaning_en), examples=[example(*a),example(*b)])
def row(level, ident, zh, form, mzh, men, *examples):
    return grammar(level, ident, zh, form, mzh, men, *examples)
def form(key, title, base, target, meaning, wrong):
    return dict(key=key,title=dict(zh=title,en=key),examples=[dict(base=base,form=target,meaning=meaning,wrong=wrong,say=None)])
def phrase(key,text,zh,en):
    return dict(key=key,text=text,meaning=dict(zh=zh,en=en),say=None,note=dict(zh='原创 Neo 教学表达，不是托尔金原文引句。',en='Original Neo practice expression, not a Tolkien quotation.'))

